                                                                                                                                                                                                      
  CREATE TABLE "TENANT_ROBOTS"                                                                                                                                                             
   (	"ROBOT_ID" NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"CREATED_BY" NUMBER(20,0) NOT NULL ENABLE,                                                                                                                                                           
	"CREATION_DATE" DATE NOT NULL ENABLE,                                                                                                                                                                
	"UPDATED_BY" NUMBER(20,0) NOT NULL ENABLE,                                                                                                                                                           
	"UPDATE_DATE" DATE NOT NULL ENABLE,                                                                                                                                                                  
	"REMARK" NVARCHAR2(512),                                                                                                                                                                             
	"DEL_FLAG" NUMBER DEFAULT 0 NOT NULL ENABLE,                                                                                                                                                         
	"TENANT_ID" NUMBER(20,0) DEFAULT 3 NOT NULL ENABLE,                                                                                                                                                  
	"NAME" NVARCHAR2(32) NOT NULL ENABLE,                                                                                                                                                                
	"WEBHOOK_URL" VARCHAR2(256) NOT NULL ENABLE,                                                                                                                                                         
	"TYPE" NVARCHAR2(32) NOT NULL ENABLE,                                                                                                                                                                
	"IS_ENABLE" NUMBER DEFAULT 0 NOT NULL ENABLE,                                                                                                                                                        
	"ENCRYPT_TYPE" NUMBER NOT NULL ENABLE,                                                                                                                                                               
	"SECRET_KEY" NVARCHAR2(100),                                                                                                                                                                         
	"BIND_TYPE" NUMBER DEFAULT 1 NOT NULL ENABLE,                                                                                                                                                        
	"BIND_REFERENCE" NUMBER(20,0),                                                                                                                                                                       
	"BASE_DEPT_ID" NVARCHAR2(36),                                                                                                                                                                        
	 PRIMARY KEY ("ROBOT_ID")                                                                                                                                                                            
  USING INDEX  ENABLE                                                                                                                                                                                 
   ) ;                                                                                                                                                                                                

